import { newSpecPage } from '@stencil/core/testing';
import { ScPhoneInput } from '../sc-phone-input';

describe('sc-phone-input', () => {
  it('ships a default pattern that is valid under the RegExp v flag and validates phone characters', () => {
    const pattern = new ScPhoneInput().pattern;

    // The v flag is what the browser uses for HTML pattern constraint validation.
    // The old default threw "Invalid character in character class" here, which
    // silently disabled format validation (SUR-5514).
    expect(() => new RegExp(pattern, 'v')).not.toThrow();
    expect(() => new RegExp(pattern)).not.toThrow();

    // The HTML pattern attribute full-matches, so anchor to mimic that.
    const anchored = new RegExp(`^(?:${pattern})$`, 'v');

    // Extensions and dial pauses must pass — the old default never actually
    // validated, so tightening it now would block checkouts that used to work.
    ['(555)123-4567', '+1 (555) 123-4567', '555.123.4567', '555-1234 ext 12', '+44 20 7123 4567 x22', '555-1234,,101'].forEach(valid => {
      expect(anchored.test(valid)).toBe(true);
    });

    ['!!!!', '555*1234', '555@1234'].forEach(invalid => {
      expect(anchored.test(invalid)).toBe(false);
    });
  });

  it('renders', async () => {
    const page = await newSpecPage({
      components: [ScPhoneInput],
      html: `<sc-phone-input></sc-phone-input>`,
    });
    expect(page.root).toMatchSnapshot();
  });
});
